-- KIỂM TRA
SELECT COUNT(*) AS `so_vat_pham_moi` FROM `item_template` WHERE `id` BETWEEN 2032 AND 2074;
SELECT COUNT(*) AS `so_part_moi` FROM `part` WHERE `id` BETWEEN 2099 AND 2212;
SELECT MAX(`id`) AS `part_lon_nhat` FROM `part`;
SELECT `id`, `NAME`, `icon_id`, `head`, `body`, `leg` FROM `item_template`
 WHERE `id` BETWEEN 2032 AND 2074 ORDER BY `id`;
